using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        // EF Core 9 breaking change: sync I/O is no longer supported for Cosmos.
        // If you cannot migrate all call sites to async immediately, you can
        // re-enable sync (temporarily) by uncommenting the line below:
        // optionsBuilder.ConfigureWarnings(w => w.Ignore(CosmosEventId.SyncNotSupported));
    }
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // BREAKING CHANGE 1 — Discriminator property renamed from "Discriminator" to "$type".
            // Existing 500K documents still store "Discriminator". Keep the old name so EF Core 9
            // can read existing data and raw SQL queries (c.Discriminator) remain valid.
            entity.HasDiscriminator<string>("Discriminator");

            // BREAKING CHANGE 2 — Id format changed from "EntityType|Key" to just "Key".
            // Existing documents have id = "Product|123". Preserve that format so existing
            // documents are still addressable.
            entity.HasPartitionKey(p => p.Id);
            entity.Property(p => p.Id).ToJsonProperty("id")
                .HasValueGenerator<LegacyCosmosIdGenerator>();
        });

        // NOTE: HasIndex() was removed for the Cosmos provider in EF Core 9 (it was a no-op).
        // Cosmos DB indexes are managed via indexing policy on the container, not via EF.
    }
}

/// <summary>
/// Generates ids in the legacy EF Core 8 format: "Product|{key}"
/// so that new writes remain compatible with existing documents.
/// </summary>
using Microsoft.EntityFrameworkCore.ChangeTracking;
using Microsoft.EntityFrameworkCore.ValueGeneration;
class LegacyCosmosIdGenerator : ValueGenerator<string>
{
    public override bool GeneratesTemporaryValues => false;
    public override string Next(EntityEntry entry)
        => $"Product|{entry.Property("Id").CurrentValue}";
}

class Product { public int Id { get; set; } public string Sku { get; set; } }

