class CosmosQuery
{
    async Task FindProductsAsync(ProductContext ctx)
    {
        // Direct Cosmos SQL — still references c.Discriminator because we configured
        // HasDiscriminator("Discriminator") to keep the EF Core 8 property name.
        var sql = "SELECT * FROM c WHERE c.Discriminator = 'Product' AND c.Sku = @sku";

        // BREAKING CHANGE 3 — Sync APIs (ToList, First, Single, etc.) are removed in
        // the EF Core 9 Cosmos provider. All queries must use async equivalents.
        var products = await ctx.Products.Where(p => p.Sku == "ABC").ToListAsync();
    }
}

